ROOT_LABEL = "Protocol design causation world"
ROOT_STATEMENT = "Root of the protocol design causation world: how framing, negotiated rules, receiver state, retry policy, application effect boundaries, and resource feedback determine correct interpretation and bounded progress."
LIMITATIONS = [
    "All prose is original; named RFC mechanisms retain their concrete protocol scope and recommendations are conditioned on implementations following them.",
    "Generic queue, retry, cancellation, and transactional-handler relations describe explicitly declared mechanism models, not features guaranteed by every RPC or deployed service.",
    "At-most-once effects, at-least-once execution, message delivery, response receipt, and durable application completion are separate properties.",
    "Failure suspicion under asynchronous delay is not proof of a crash, and the end-to-end argument is a design guideline rather than a prohibition on useful lower-layer mechanisms.",
]

